        "while true; do wget -q -O /dev/null --no-check-certificate --header \"Authorization: Bearer $(cat /var/run/secrets/kubernetes.io/serviceaccount/token)\" https://kubernetes.default.svc/api/v1/namespaces/default/configmaps/app-config && echo api-ok || echo api-fail; sleep 10; done"
